import Ajv from 'ajv';
const compileSpy = jest.spyOn(Ajv.prototype, 'compile');
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('passes valid input with extra properties through unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    const calls: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
      },
      async input => {
        calls.push(input);
        return 'ok';
      }
    );

    const input = {a: 'val', extra: 'prop'};
    await registry.execute('test_tool', input);

    expect(calls).toEqual([input]);
    expect(calls[0]).toBe(input);
  });

  it('validates against a dynamic schema that changes between calls', async () => {
    const registry = new ToolRegistry();
    let requiredProp = 'first';
    registry.register(
      () => ({
        name: 'dynamic_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {[requiredProp]: {type: 'string'}},
          required: [requiredProp],
        },
      }),
      async () => 'ok'
    );

    const firstResult = await registry.execute('dynamic_tool', {first: 'val'});
    expect(firstResult.result).toBe('ok');

    const firstFailure = await registry.execute('dynamic_tool', {second: 'val'});
    expect(firstFailure.result).toMatch(/first/);

    requiredProp = 'second';
    const secondResult = await registry.execute('dynamic_tool', {second: 'val'});
    expect(secondResult.result).toBe('ok');

    const secondFailure = await registry.execute('dynamic_tool', {first: 'val'});
    expect(secondFailure.result).toMatch(/second/);
  });

  it('compiles a static tool schema once across ten execute calls', async () => {
    const registry = new ToolRegistry();
    const schema = {type: 'object', properties: {a: {type: 'string'}}};
    registry.register(
      {
        name: 'static_tool',
        description: 'test',
        inputSchema: schema,
      },
      async () => 'ok'
    );

    const countAfterRegister = compileSpy.mock.calls.length;

    for (let i = 0; i < 10; i++) {
      await registry.execute('static_tool', {a: 'val'});
    }

    expect(compileSpy).toHaveBeenCalledTimes(countAfterRegister);
  });

  it('throws Unknown tool for an unregistered name', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('nonexistent', {})).rejects.toThrow('Unknown tool: nonexistent');
  });
});

